import json
from pathlib import Path
from series_build import parse_pairs
pages={}
def P(i,t,v='',s='',qa=None,note=None):
    pages[i]=dict(topic=t,v=parse_pairs(v),s=parse_pairs(s),qa=qa or [])
    if note:pages[i]['note']=note
def V(i,t,v,s=''):
    P(i,t,v,s);return v

P(4,'Chuẩn bị đồ ăn cho tiệc',s="Is everything ready for the party?=Mọi thứ cho bữa tiệc đã sẵn sàng chưa?|I think so.=Mình nghĩ rồi.|Are there any pretzels?=Có bánh pretzel không?|Yes, there are.=Có.|How many cans are there?=Có bao nhiêu lon?|There are ten cans of soda.=Có mười lon nước ngọt.|Should I bring some cake?=Mình có nên mang ít bánh ngọt không?|Yes, that's a good idea.=Có, đó là ý hay.",qa=[('How many cans are there?','There are ten cans of soda.'),('Should I bring some cake?',"Yes, that's a good idea.")])
